import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_PROGRAMA, MODELO_EMISORA, TABLA_PROGRAMAS } from '../../models/emisora-programa.model.mjs';

export async function buscarEmisoraRepository(emisoraId) {
  const { Item } = await MODELO_EMISORA.build(GetItemCommand)
    .key({ emisoraId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEmisoraRepository(emisoraId, minimo) {
  const { Items = [] } = await TABLA_PROGRAMAS.build(QueryCommand)
    .entities(MODELO_PROGRAMA)
    .query({ index: 'PorEmisora', partition: emisoraId })
    .options({ filters: { Programa: { attr: 'duracionMinutos', gte: minimo } } })
    .send();
  return Items;
}
